"""corpus.py — test helpers: the GATE-1-certified v2 crossbar and GEMM corpora, regenerated by the copied v2 case
generators into v3/work/corpus/<name>/ (byte-identical to v2's, F1), and decoders for their .mem files.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
from pathlib import Path

import numpy as np

V3 = Path(__file__).resolve().parents[2]
REPO = V3.parent
CORPUS = V3 / "work" / "corpus"
GENERATORS = {
    "dpe": ("ip/xbar/tb/gen_cases.py", ()),
    "dpe_p29": ("ip/xbar/tb/gen_cases.py", ("--p29",)),
    "gemm": ("ip/gemm/tb/gen_gemm_cases.py", ()),
    "gemm_p29": ("ip/gemm/tb/gen_gemm_cases.py", ("--p29",)),
}


def ensure(name: str) -> Path:
    """The corpus directory, generated with the copied generator's default arguments if it is not there yet."""
    out = CORPUS / name
    if not (out / "manifest.txt").exists():
        gen, args = GENERATORS[name]
        env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1", TMPDIR=str(V3 / "work" / "tmp"))
        (V3 / "work" / "tmp").mkdir(parents=True, exist_ok=True)
        subprocess.run([sys.executable, str(V3 / gen), "--out", str(out), *args], cwd=REPO, env=env, check=True,
                       stdout=subprocess.DEVNULL)
    return out


def cases(path: Path) -> list:
    """[(case dir, case.json)] in manifest order."""
    names = [n for n in (path / "manifest.txt").read_text().split() if n]
    return [(path / n, json.loads((path / n / "case.json").read_text())) for n in names]


def readWords(path: Path) -> np.ndarray:
    return np.array([int(line, 16) for line in path.read_text().split()], dtype=np.uint64)


def wordsToBytes(words: np.ndarray, n: int) -> np.ndarray:
    """The first n bytes of 40-bit words (byte i of a word = bits 8i+7:8i), as int8."""
    shifts = np.arange(5, dtype=np.uint64) * np.uint64(8)
    b = ((words[:, None] >> shifts[None, :]) & np.uint64(0xFF)).astype(np.uint8).reshape(-1)
    if b.size < n:
        raise ValueError(f"{b.size} bytes in the stream, {n} needed")
    return b[:n].view(np.int8)


def readOutLines(path: Path) -> np.ndarray:
    """expected_out.mem: one line per pass, two hex digits per byte -> uint8 [M, bytes]."""
    return np.array([[int(line[i:i + 2], 16) for i in range(0, len(line), 2)] for line in path.read_text().split()],
                    dtype=np.uint8)
